/** Text with numbers or names in it. Each entry is [pattern, builder]; tr is available for nested pieces. */
type Tr = (s: string) => string;
export const EL_PATTERNS: [RegExp, (t: Tr, ...m: string[]) => string][] = [
  [/^Week (\d+) of (\d+)(, deload)?$/, (t, a, b, d) => `Εβδομάδα ${a} από ${b}${d ? ", εκφόρτιση" : ""}`],
  [/^Week (\d+), (\d+) of (\d+) sets$/, (t, w, a, b) => `Εβδομάδα ${w}, ${a} από ${b} σετ`],
  [/^(.+), week (\d+)$/, (t, a, b) => `${t(a)}, εβδομάδα ${b}`],
  [/^(.+), block (\d+)$/, (t, a, b) => `${t(a)}, μπλοκ ${b}`],
  [/^(\d+) exercises?(,?)$/, (t, a, c) => `${a} ασκήσεις${c}`],
  [/^(\d+) sets?(,?)$/, (t, a, c) => `${a} σετ${c}`],
  [/^Week (\d+) is done\. Go to week (\d+)$/, (t, a, b) => `Η εβδομάδα ${a} ολοκληρώθηκε. Πήγαινε στην εβδομάδα ${b}`],
  [/^Create "(.+)"$/, (t, a) => `Δημιουργία "${a}"`],
  [/^Sets updated in (\d+) weeks?$/, (t, a) => `Τα σετ ενημερώθηκαν σε ${a} εβδομάδ${a === "1" ? "α" : "ες"}`],
  [/^Same muscle \((.+)\)\. Loads reset to the new lift's history\.$/, (t, a) => `Ίδιος μυς (${a}). Τα φορτία ξεκινούν από το ιστορικό της νέας άσκησης.`],
  [/^Account: (.+)$/, (t, a) => `Λογαριασμός: ${a}`],
  [/^\+ Mini-set, rest (\d+) s$/, (t, a) => `+ Μίνι-σετ, ξεκούραση ${a} δ`],
  [/^Set (\d+) myo-reps$/, (t, a) => `Σετ ${a} myo-reps`],
  [/^Set (\d+) mini-sets$/, (t, a) => `Μίνι-σετ του σετ ${a}`],
  [/^Set (\d+) mini-set (\d+) reps$/, (t, a, b) => `Σετ ${a}, μίνι-σετ ${b}, επαναλήψεις`],
  [/^Week (\d+)$/, (t, a) => `Εβδομάδα ${a}`],
  [/^W(\d+)$/, (t, a) => `Ε${a}`],
  [/^Block (\d+)$/, (t, a) => `Μπλοκ ${a}`],
  [/^(\d+) exercises?, (\d+) sets?(?:, (.+))?$/, (t, a, b, r) => `${a} ασκήσεις, ${b} σετ${r ? ", " + t(r) : ""}`],
  [/^(\d+) sets?$/, (t, a) => `${a} σετ`],
  [/^(\d+) exercises?\.(.*)$/, (t, a, r) => `${a} ασκήσεις.${t(r)}`],
  [/^(\d+) sessions logged(?:, last (.+))?$/, (t, a, r) => `${a} προπονήσεις καταγράφηκαν${r ? ", τελευταία " + r : ""}`],
  [/^Superset of (\d+): alternate, rest after the last$/, (t, a) => `Σούπερσετ ${a} ασκήσεων: εναλλάξ, ανάπαυση μετά την τελευταία`],
  [/^Set (\d+) (weight|reps in reserve|RIR|RPE)$/, (t, a, k) => `Σετ ${a} ${k === "weight" ? "βάρος" : k === "reps in reserve" ? "εφεδρεία επαναλήψεων" : k}`],
  [/^Set (\d+) done$/, (t, a) => `Σετ ${a} ολοκληρώθηκε`],
  [/^Set (\d+): Heaviest yet: (.+) kg x (\d+) \(was (.+)\)$/, (t, a, w, r, p) => `Σετ ${a}: Το βαρύτερο μέχρι τώρα: ${w} kg x ${r} (ήταν ${p})`],
  [/^Set (\d+): Predicts a (.+) kg 1RM, up (.+)$/, (t, a, e, d) => `Σετ ${a}: Προβλέπει 1RM ${e} kg, αύξηση ${d}`],
  [/^Set (\d+): Best e1RM at about (.+) kg bodyweight: (.+) kg$/, (t, a, b, e) => `Σετ ${a}: Καλύτερο e1RM με σωματικό βάρος περίπου ${b} kg: ${e} kg`],
  [/^Set (\d+): (.+) x bodyweight, was (.+)$/, (t, a, x, p) => `Σετ ${a}: ${x} x σωματικό βάρος, ήταν ${p}`],
  [/^Set (\d+): More reps at (.+) kg: (.+) \(was (.+)\)$/, (t, a, w, r, p) => `Σετ ${a}: Περισσότερες επαναλήψεις στα ${w} kg: ${r} (ήταν ${p})`],
  [/^Aim (.+) for (.+) reps$/, (t, w, r) => `Στόχος ${w} για ${r} επαναλήψεις`],
  [/^Aim for (.+) reps$/, (t, r) => `Στόχος ${r} επαναλήψεις`],
  [/^(.*), plan (RIR|RPE) (\d+)(.*)$/, (t, m, k, n, r) => `${t(m)}, πλάνο ${k} ${n}${r.replace(/, \+(\d+)% bodyweight/, ", +$1% σωματικό βάρος").replace(/ base$/, " βάση")}`],
  [/^target (\d+(?:\.\d)?)$/, (t, a) => `στόχος ${a}`],
  [/^Renamed to (.+)$/, (t, a) => `Μετονομάστηκε σε ${a}`],
  [/^(.+) added$/, (t, a) => `Προστέθηκε: ${a}`],
  [/^Added contributors to (\d+) exercises$/, (t, a) => `Προστέθηκαν δευτερεύοντες μύες σε ${a} ασκήσεις`],
  [/^(\d+) exercises\.(.*)$/, (t, a, r) => `${a} ασκήσεις.${t(r)}`],
  [/^Use (.+) as squat$/, (t, a) => `Χρήση ${a} ως καθιστή`],
  [/^Sent to (.+)$/, (t, a) => `Στάλθηκε σε ${a}`],
  [/^(.+) sent to (.+)$/, (t, a, b) => `Το ${a} στάλθηκε σε ${b}`],
  [/^(.+) is now a coach$/, (t, a) => `Ο/Η ${a} είναι πλέον προπονητής`],
  [/^(.+) is now an athlete$/, (t, a) => `Ο/Η ${a} είναι πλέον αθλητής`],
  [/^This invite is for (.+)\. Use that address\.$/, (t, a) => `Αυτή η πρόσκληση είναι για το ${a}. Χρησιμοποίησε αυτή τη διεύθυνση.`],
  [/^Open until (.+)$/, (t, a) => `Ανοιχτή έως ${a}`],
  [/^Used by (.+)$/, (t, a) => `Χρησιμοποιήθηκε από ${a}`],
  [/^Synced at (.+)$/, (t, a) => `Συγχρονίστηκε στις ${a}`],
  [/^Sync problem: (.+)$/, (t, a) => `Πρόβλημα συγχρονισμού: ${t(a)}`],
  [/^Build (\d+)(.*)$/, (t, a, r) => `Έκδοση ${a}${r}`],
  [/^Last (\d+)$/, (t, a) => `Τελευταίες ${a}`],
  [/^Total (\d+(?:\.\d)?) kg$/, (t, a) => `Σύνολο ${a} kg`],
  [/^Pending ratings: (\d+)\. Pump scale: (.+)\.$/, (t, a, p) => `Εκκρεμείς βαθμολογίες: ${a}. Κλίμακα pump: ${p.split(", ").map(t).join(", ")}.`],
  [/^Rename (.+)$/, (t, a) => `Μετονομασία ${a}`],
  [/^Edit (.+)$/, (t, a) => `Επεξεργασία ${a}`],
  [/^Remove (.+)$/, (t, a) => `Αφαίρεση ${a}`],
  [/^Notes: (.+)$/, (t, a) => `Σημειώσεις: ${a}`],
  [/^Note: (.+)$/, (t, a) => `Σημείωση: ${a}`],
  [/^Swap (.+)$/, (t, a) => `Αλλαγή ${a}`],
  [/^Warm-up for (.+)$/, (t, a) => `Προθέρμανση για ${a}`],
  [/^Same muscle \((.+)\)\. Loads reset to the new lift's history\.$/, (t, a) => `Ίδιος μυς (${a}). Τα φορτία ξεκινούν από το ιστορικό της νέας άσκησης.`],
  [/^Last (.+)x(\d+)$/, (t, a, b) => `Προηγ. ${a}x${b}`],
  [/^Superset with (.+)$/, (t, a) => `Σούπερσετ με ${a}`],
  [/^Weeks? (\d+)$/, (t, a) => `Εβδομάδα ${a}`],
  [/^Editing the sessions of week (\d+)\. Adjustments from feedback stay layered on top\.$/, (t, a) => `Επεξεργασία των προπονήσεων της εβδομάδας ${a}. Οι προσαρμογές από την ανατροφοδότηση μένουν από πάνω.`],
  [/^Week (\d+) only$/, (t, a) => `Μόνο εβδομάδα ${a}`],
  [/^Week (\d+) onward$/, (t, a) => `Από την εβδομάδα ${a} και μετά`],
  [/^Weekly split, week (\d+)$/, (t, a) => `Εβδομαδιαίο πρόγραμμα, εβδομάδα ${a}`],
  [/^Not scheduled this week: (.+)\.$/, (t, a) => `Δεν έχουν προγραμματιστεί αυτή την εβδομάδα: ${a}.`],
  [/^Sessions in week (\d+)$/, (t, a) => `Προπονήσεις εβδομάδας ${a}`],
  [/^(\d+) older sessions have no date\..*$/, (t, a) => `${a} παλιότερες προπονήσεις δεν έχουν ημερομηνία. Όρισε την ημερομηνία έναρξης του μεσοκύκλου και ημερομηνούνται με το εβδομαδιαίο πρόγραμμά σου.`],
  [/^(\d+) exercises mapped to muscles\..*$/, (t, a) => `${a} ασκήσεις αντιστοιχισμένες σε μυς. Διόρθωσε μια λάθος αντιστοίχιση στο Περισσότερα, Βιβλιοθήκη ασκήσεων.`],
  [/^(\d+) weigh-ins$/, (t, a) => `${a} ζυγίσεις`],
  [/^Preview: (.+)$/, (t, a) => `Προεπισκόπηση: ${a}`],
  [/^(.*) to (.*)$/, (t, a, b) => (/^\d+$/.test(a) && /^\d+$/.test(b)) ? `${a} έως ${b}` : `${a} to ${b}`],
];
